// Aborta la corrida si LM Studio o SQLite están mal (decisión 7 del plan).
const raw = $input.first().json.stdout || '';
let informe = null;
try { informe = JSON.parse(raw); } catch (e) { throw new Error('guardian.py no devolvió JSON. Salida: ' + raw.slice(0, 300)); }
const checks = informe.checks || {};
const malos = Object.entries(checks).filter(([k, v]) => v.estado === 'error').map(([k]) => k);
if (malos.includes('lmstudio') || malos.includes('sqlite')) {
  throw new Error('Sistema no sano, no arranco el aprendizaje web: ' + malos.join(', '));
}
return [{ json: { peor: informe.peor || 'ok', avisos: malos.join(',') || 'ninguno' } }];

// Parsea el stdout de ingesta_web.py --contexto (JSON ASCII, §11.1).
const raw = $input.first().json.stdout || '';
let contexto;
try { contexto = JSON.parse(raw); } catch (e) { throw new Error('--contexto no devolvió JSON válido: ' + raw.slice(0, 300)); }
return [{ json: { contexto } }];

/* PLANIFICADOR (versión determinista; ver variante con qwen3.5-4b en
 * sección 2 de este mismo archivo, en el comentario del nodo). Reparte max_consultas entre:
 *  1) releases Atom + RSS de la watchlist (criterios_busqueda.json, llegan en --contexto)
 *  2) búsqueda GitHub/HuggingFace por los temas de mayor peso efectivo.
 * Cada consulta lleva su DISPARADOR obligatorio (Context.md invariante 11):
 * hueco | dominio_vigilado | peticion. Ninguna URL se arma con texto web:
 * solo keywords propias, codificadas con encodeURIComponent. */
const MAX_URL_LEN = 500;
const HOSTS_API = new Set(['api.github.com','huggingface.co','github.com','blog.n8n.io','ollama.com','openwebui.com','news.ycombinator.com','reddit.com','www.reddit.com','phoronix.com','github.blog']);

const ctx = $('Parsear contexto').first().json.contexto;
const pesos = ctx.pesos_efectivos || {};
const huecos = ctx.huecos || [];
const limites = ctx.limites_por_ciclo || {};
const maxConsultas = Math.max(1, Math.min(Number(limites.max_consultas) || 8, 8));
const setHuecos = new Set(huecos.map(h => String(h.interes).toLowerCase()));

function esSegura(u) {
  if (!u || String(u).length > MAX_URL_LEN) return false;
  let x; try { x = new URL(u); } catch (e) { return false; }
  if (x.protocol !== 'https:') return false;
  let host = x.hostname.toLowerCase();
  if (host.startsWith('www.')) host = host.slice(4);
  return HOSTS_API.has(host);
}
function slug(s) { return String(s).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 40) || 'tema'; }
function q(t) { return String(t).toLowerCase().replace(/[^\w\sáéíóúñü-]/g, ' ').replace(/\s+/g, ' ').trim().split(' ').filter(w => w.length >= 3).slice(0, 6).join(' '); }

const consultas = [];
const vistos = new Set();
function add(c) {
  if (!c || !esSegura(c.url)) return;
  const clave = c.disparador.tipo + '|' + c.disparador.detalle;
  if (vistos.has(clave)) return;
  vistos.add(clave);
  consultas.push(c);
}

// 1) Watchlist fija: releases Atom primero (novedades duras), luego RSS.
for (const f of (ctx.releases_atom || [])) {
  if (consultas.length >= maxConsultas) break;
  add({ url: f.url, tipo_fuente: 'releases_atom', nombre: f.nombre || slug(f.url), ruido: 'bajo',
        disparador: { tipo: 'dominio_vigilado', detalle: 'release: ' + (f.nombre || f.url) } });
}
for (const f of (ctx.fuentes_rss || [])) {
  if (consultas.length >= maxConsultas) break;
  add({ url: f.url, tipo_fuente: 'rss', nombre: f.nombre || slug(f.url), ruido: f.ruido || 'bajo',
        disparador: { tipo: 'dominio_vigilado', detalle: 'rss: ' + (f.nombre || f.url) } });
}

// 2) Búsquedas por tema, ordenadas por peso efectivo (+0.5 bonus si hay hueco).
const temas = Object.keys(pesos)
  .map(nombre => ({ nombre, p: (Number(pesos[nombre]) || 0.5) + (setHuecos.has(nombre.toLowerCase()) ? 0.5 : 0) }))
  .sort((a, b) => b.p - a.p);
let i = 0;
for (const tema of temas) {
  if (consultas.length >= maxConsultas) break;
  const kw = q(tema.nombre);
  if (!kw) continue;
  const tipoDisp = setHuecos.has(tema.nombre.toLowerCase()) ? 'hueco' : 'dominio_vigilado';
  const mod = i % 3; i++;
  if (mod === 1) {
    add({ url: 'https://huggingface.co/api/models?search=' + encodeURIComponent(kw) + '&sort=lastModified&direction=-1&limit=15',
          tipo_fuente: 'huggingface_api', nombre: tema.nombre, ruido: 'bajo',
          disparador: { tipo: tipoDisp, detalle: tema.nombre } });
  } else {
    const extra = mod === 2 ? ' in:description' : '';
    add({ url: 'https://api.github.com/search/repositories?q=' + encodeURIComponent(kw + extra) + '&sort=updated&order=desc&per_page=15',
          tipo_fuente: 'github_api', nombre: tema.nombre, ruido: 'bajo',
          disparador: { tipo: tipoDisp, detalle: tema.nombre } });
  }
}

return consultas.map(c => ({ json: c }));

/* Normaliza la respuesta de cada fuente a candidatos planos:
 * {url, titulo, fecha_publicacion, snippet, fuente, tipo_fuente, disparador}.
 * El contenido externo es DATO: solo se leen campos conocidos; nunca se ejecuta
 * ni se interpola en comandos (§10). Status >= 400 -> marcador de fuente fallida.
 * Parsing XML propio (robusto): n8n no garantiza $parseXml en el nodo Code. */
const resp = $input.first().json;
// La consulta viaja pegada a la respuesta gracias a "Include Input" del HTTP Request.
const consulta = resp;
const status = Number(resp.statusCode || resp.status || 200);
if (status >= 400) {
  return [{ json: { _fuente_fallida: consulta.url, _status: status } }];
}

// Body: JSON ya parseado (GitHub/HF) o string XML (Atom/RSS).
let body = (resp.data !== undefined) ? resp.data : resp.body;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) { body = { _xml: body }; }
}

function desentitatizar(s) {
  return String(s == null ? '' : s)
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
    .replace(/&#39;|&apos;/g, "'").replace(/&amp;/g, '&');
}
function txt(v, n) { return desentitatizar(v).replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, n); }
function isoDe(f) {
  if (!f) return null;
  const d = new Date(desentitatizar(f));
  return isNaN(d.getTime()) ? null : d.toISOString().slice(0, 10);
}
// Extrae bloques <entry>/<item> y adentro el primer texto de una etiqueta.
function bloques(xml, tag) {
  const re = new RegExp('<' + tag + '(?:\\s[^>]*)?>([\\s\\S]*?)</' + tag + '>', 'gi');
  const out = []; let m;
  while ((m = re.exec(xml)) && out.length < 15) out.push(m[1]);
  return out;
}
function campo(bloque, tag) {
  // con atributos (href) o texto plano
  const attr = new RegExp('<' + tag + '[^>]*\\bhref="([^"]+)"', 'i').exec(bloque);
  if (attr) return attr[1];
  const re = new RegExp('<' + tag + '(?:\\s[^>]*)?>([\\s\\S]*?)</' + tag + '>', 'i');
  const m = re.exec(bloque);
  if (!m) return '';
  return desentitatizar(m[1].replace(/<!\[CDATA\[[\s\S]*?\]\]>/g, s => s.slice(9, -3)));
}

const candidatos = [];
const tipo = consulta.tipo_fuente;

if (tipo === 'github_api' && body && Array.isArray(body.items)) {
  for (const r of body.items.slice(0, 15)) {
    candidatos.push({
      url: r.html_url, titulo: r.full_name,
      fecha_publicacion: isoDe(r.pushed_at || r.updated_at),
      snippet: txt(r.description, 400), fuente: 'github.com',
      estrellas: r.stargazers_count || 0,
    });
  }
} else if (tipo === 'huggingface_api' && Array.isArray(body)) {
  for (const m of body.slice(0, 15)) {
    candidatos.push({
      url: 'https://huggingface.co/' + m.modelId, titulo: m.modelId,
      fecha_publicacion: isoDe(m.lastModified),
      snippet: txt(m.pipeline_tag || '') + ' | descargas: ' + (m.downloads ?? '?'),
      fuente: 'huggingface.co',
    });
  }
} else if ((tipo === 'releases_atom' || tipo === 'rss') && typeof (body._xml || '') === 'string') {
  const xml = body._xml;
  const blocks = bloques(xml, 'entry').length ? bloques(xml, 'entry') : bloques(xml, 'item');
  for (const b of blocks) {
    const url = campo(b, 'link');
    candidatos.push({
      url: /^https?:\/\//.test(url) ? url : '',
      titulo: txt(campo(b, 'title'), 200),
      fecha_publicacion: isoDe(campo(b, 'published') || campo(b, 'updated') || campo(b, 'pubDate') || campo(b, 'dc:date')),
      snippet: txt(campo(b, 'summary') || campo(b, 'description') || campo(b, 'content:encoded') || campo(b, 'content'), 400),
      fuente: (() => { try { return new URL(url).hostname.replace(/^www\./, ''); } catch (e) { return 'desconocida'; } })(),
      ruido: consulta.ruido || 'bajo',
    });
  }
}

return candidatos
  .filter(c => /^https:\/\/.+/.test(c.url || ''))
  .map(c => ({ json: { ...c, tipo_fuente: tipo, disparador: consulta.disparador, fuente_consulta: consulta.nombre } }));

/* FILTRAR CANDIDATOS (§5 paso 5): dedupe por URL canónica contra urls_vistas y
 * dentro del ciclo, antigüedad ≤ max_antiguedad_dias, palabras de descarte y
 * tope max_hallazgos. Las fuentes que fallaron se listan en _avisos. */
const ctx = $('Parsear contexto').first().json.contexto;
const vistas = new Set((ctx.urls_vistas || []).map(normalizarUrl).filter(Boolean));
const descartarPalabras = (ctx.descartar || []).map(s => String(s).toLowerCase());
const maxDias = Number(ctx.max_antiguedad_dias) || 365;
const maxHallazgos = Number((ctx.limites_por_ciclo || {}).max_hallazgos) || 20;
const hoy = new Date();

function normalizarUrl(u) {
  try {
    const x = new URL(String(u).trim());
    let host = x.hostname.toLowerCase(); if (host.startsWith('www.')) host = host.slice(4);
    for (const k of [...x.searchParams.keys()]) if (/^utm_|^ref$|fbclid|ga_source/i.test(k)) x.searchParams.delete(k);
    const path = x.pathname.replace(/\/+$/, '') || '/';
    return host + path + (x.search ? '?' + x.searchParams.toString() : '');
  } catch (e) { return null; }
}
function fechaValida(f) {
  if (!f) return true;
  const d = new Date(f);
  if (isNaN(d.getTime())) return true;
  if (d > new Date(hoy.getTime() + 2 * 864e5)) return false;
  return (hoy - d) / 864e5 <= maxDias;
}

// Recolección: todos los ítems que llegaron de la rama (incluye marcadores _fuente_fallida)
const itemsAll = $input.all();
const fallidas = itemsAll.map(i => i.json).filter(j => j._fuente_fallida).map(j => j._fuente_fallida + ' (' + j._status + ')');
const crudos = itemsAll.map(i => i.json).filter(j => j.url && !j._fuente_fallida);

const vistosCiclo = new Set();
const salida = [];
for (const j of crudos) {
  const u = normalizarUrl(j.url);
  if (!u || vistas.has(u) || vistosCiclo.has(u)) continue;
  if (!fechaValida(j.fecha_publicacion)) continue;
  const s = ((j.titulo || '') + ' ' + (j.snippet || '')).toLowerCase();
  if (descartarPalabras.some(p => s.includes(p))) continue;
  vistosCiclo.add(u);
  salida.push({ json: { ...j, url_canonica: u } });
  if (salida.length >= maxHallazgos) break;
}
if (salida.length === 0) {
  return [{ json: { _resumen: 'sin candidatos nuevos', _fallidas: fallidas.join(', ') || 'ninguna' } }];
}
return salida;

