// Fin del bucle: junta los candidatos normalizados de TODAS las consultas.
// En n8n, al terminar Split In Batches por la salida 'done', recuperamos los items
// que produjo 'Normalizar candidatos' en esta ejecución completa.
const items = $('Normalizar candidatos').all()
  .map(i => i.json)
  .filter(j => j.url || j._fuente_fallida);
if (items.length === 0) {
  return [{ json: { _resumen: 'sin candidatos nuevos', _fallidas: 'ninguna fuente devolvió ítems' } }];
}
return items.map(j => ({ json: j }));
